fn('capture', '''  function capture(){const form=$('#answers-form');if(!form||!formId)return;const s=visibleSections(schema())[sectionIndex];if(s?.owner!==actor)return;for(const field of s.fields){if(!isVisible(schema(),field)||field.type==='calculated'||field.readonly||field.readOnly)continue;let value;if(field.type==='table'){const rows=clone(formDraft[field.id]||field.fixedRows||[]);for(let i=0;i<rows.length;i++)for(const col of field.columns){if(col.readonly||col.readOnly||col.type==='calculated')continue;const els=[...form.querySelectorAll(`[data-table="${field.id}"][data-row="${i}"][data-field="${col.id}"]`)];if(!els.length)continue;rows[i][col.id]=col.type==='checkbox_group'?els.filter(el=>el.checked).map(el=>el.dataset.option):readControl(els[0],col);}value=rows;}else if(field.type==='checkbox_group'){value=[...form.querySelectorAll(`[data-field="${field.id}"][data-option]:checked`)].map(el=>el.dataset.option);}else{const el=form.querySelector(`[data-field="${field.id}"]`);if(!el)continue;value=readControl(el,field);}if(JSON.stringify(value)!==JSON.stringify(formDraft[field.id])){formDraft[field.id]=value;if(field.bind)for(const x of fields(schema()))if(x.owner===actor&&x.field.bind===field.bind)formDraft[x.field.id]=clone(value);}}}''')
